#!/bin/sh
# Payment Initiation v2 — YOUR review (a person's decisions; an agent never runs these). Made-up data.
# Read each block, change what you disagree with, then run:  REVIEWER="Your Name" sh work/payment-initiation-v2/review-v2.sh
set -e
R="${REVIEWER:?set REVIEWER to your name}"
WS=work/payment-initiation-v2/ws

# 1. AID inferred 9 data entities for BIAN objects. Recommended: KEEP payee, funding check and compliance check (the hub stores them);
#    REJECT the other 6 — payment transaction and account are already stored (payment_instruction, account_cache); party, payer and the
#    banks are reference data mastered outside the payments hub.
sdem aid confirm AID-ENT-COMPLIANCE-CHECK AID-ENTF-COMPLIANCE-CHECK-COMPLIANCECHECKTYPE AID-ENT-FUNDING-CHECK AID-ENTF-FUNDING-CHECK-ASSESSMENTTYPE AID-ENTF-FUNDING-CHECK-ASSESSMENTMETHOD AID-ENTF-FUNDING-CHECK-ASSESSMENTSCHEDULE AID-ENTF-FUNDING-CHECK-ASSESSMENTDESCRIPTION AID-ENTF-FUNDING-CHECK-ASSESSMENTMODEL AID-ENTF-FUNDING-CHECK-ASSESSMENTDATETIME AID-ENTF-FUNDING-CHECK-ASSESSMENTRESULT AID-ENTF-FUNDING-CHECK-ASSESSMENTSUPPORTINGDOCUMENT AID-ENTF-FUNDING-CHECK-ASSESSMENTREPRESENTINGDOCUMENT AID-ENTF-FUNDING-CHECK-ASSESSMENTREQUIREDADJUSTMENT AID-ENTF-FUNDING-CHECK-ASSESSMENTREQUIREMENT AID-ENTF-FUNDING-CHECK-ASSESSMENTEXPIRYDATE AID-ENTF-FUNDING-CHECK-ASSESSMENTSTATUS AID-ENTF-FUNDING-CHECK-ASSESSMENTIDENTIFICATION AID-ENT-PAYEE AID-ENTF-PAYEE-PAYEEIDENTIFIER AID-ENTF-PAYEE-PAYMENTINSTRUCTIONINVOLVEMENTTYPE --workspace "$WS" --person "$R"
sdem aid reject AID-ENT-ACCOUNT AID-ENTF-ACCOUNT-ACCOUNTSTATUS AID-ENTF-ACCOUNT-ACCOUNTIDENTIFICATION AID-ENTF-ACCOUNT-ACCOUNTDATE AID-ENTF-ACCOUNT-ACCOUNTTYPE AID-ENTF-ACCOUNT-ACCOUNTPURPOSE AID-ENTF-ACCOUNT-ACCOUNTBALANCE AID-ENTF-ACCOUNT-ACCOUNTCURRENCY AID-ENTF-ACCOUNT-ACCOUNTDESCRIPTION AID-ENTF-ACCOUNT-ACCOUNTNAME AID-ENTF-ACCOUNT-LOGTYPE AID-ENTF-ACCOUNT-LOGPERIOD AID-ENTF-ACCOUNT-LOGDATE AID-ENTF-ACCOUNT-LOGIDENTIFICATION AID-ENT-PARTY AID-ENTF-PARTY-PARTY-REFERENCE AID-ENTF-PARTY-PARTYNAME AID-ENTF-PARTY-PARTYTYPE AID-ENTF-PARTY-PARTYDATETIME AID-ENTF-PARTY-PARTYIDENTIFICATION AID-ENTF-PARTY-PARTYLEGALSTRUCTURETYPE AID-ENTF-PARTY-PARTYACTIVITYINDICATOR AID-ENT-PAYEE-BANK AID-ENTF-PAYEE-BANK-PAYEEBANKIDENTIFIER AID-ENTF-PAYEE-BANK-PAYMENTINSTRUCTIONINVOLVEMENTTYPE AID-ENTF-PAYEE-BANK-PARTYROLETYPE AID-ENTF-PAYEE-BANK-PARTYROLENAME AID-ENTF-PAYEE-BANK-PARTYROLEVALIDITYPERIOD AID-ENTF-PAYEE-BANK-PARTYINVOLVEMENTTYPE AID-ENT-PAYER AID-ENTF-PAYER-PAYERIDENTIFIER AID-ENTF-PAYER-PAYMENTINSTRUCTIONINVOLVEMENTTYPE AID-ENT-PAYER-BANK AID-ENTF-PAYER-BANK-PAYERBANKIDENTIFIER AID-ENTF-PAYER-BANK-PAYMENTINSTRUCTIONINVOLVEMENTTYPE AID-ENT-PAYMENT-TRANSACTION AID-ENTF-PAYMENT-TRANSACTION-PAYMENTTRANSACTIONTYPE AID-ENTF-PAYMENT-TRANSACTION-PAYMENTTRANSACTIONAMOUNT AID-ENTF-PAYMENT-TRANSACTION-PAYMENTTRANSACTIONIDENTIFICATION AID-ENTF-PAYMENT-TRANSACTION-PAYMENTTRANSACTIONUSEDMECHANISM AID-ENTF-PAYMENT-TRANSACTION-PAYMENTTRANSACTIONDATETIME AID-ENTF-PAYMENT-TRANSACTION-PAYMENTTRANSACTIONPURPOSE AID-ENTF-PAYMENT-TRANSACTION-PAYMENTTRANSACTIONSTATUS AID-ENTF-PAYMENT-TRANSACTION-PAYMENTTRANSACTIONAPPLIEDFEEAMOUNT AID-ENTF-PAYMENT-TRANSACTION-PAYMENTTRANSACTIONCURRENCY AID-ENTF-PAYMENT-TRANSACTION-PAYMENTTRANSACTIONCREDITDEBITINDICATOR AID-ENTF-PAYMENT-TRANSACTION-TRANSACTIONIDENTIFICATION AID-ENTF-PAYMENT-TRANSACTION-TRANSACTIONDATE AID-ENTF-PAYMENT-TRANSACTION-TRANSACTIONTYPE AID-ENTF-PAYMENT-TRANSACTION-TRANSACTIONDESCRIPTION AID-ENTF-PAYMENT-TRANSACTION-TRANSACTIONSTATUS AID-ENTF-PAYMENT-TRANSACTION-TRANSACTIONNAME AID-ENTF-PAYMENT-TRANSACTION-UNDERTAKINGTRANSACTIONTYPE AID-ENTF-PAYMENT-TRANSACTION-MONEYTRANSFERTRANSACTIONAMOUNT AID-ENTF-PAYMENT-TRANSACTION-MONEYTRANSFERTRANSACTIONCURRENCY AID-ENTF-PAYMENT-TRANSACTION-MONEYTRANSFERTRANSACTIONSOURCEACCOUNT AID-ENTF-PAYMENT-TRANSACTION-MONEYTRANSFERTRANSACTIONTARGETACCOUNT AID-ENTF-PAYMENT-TRANSACTION-MONEYTRANSFERINSTRUCTIONREFERENCE AID-ENTF-PAYMENT-TRANSACTION-MONEYTRANSFERUSEDMETHOD AID-ENTF-PAYMENT-TRANSACTION-MONEYTRANSFERVALUEDATE AID-ENTF-PAYMENT-TRANSACTION-FINANCIALTRANSACTIONTYPE AID-ENTF-PAYMENT-TRANSACTION-FINANCIALTRANSACTIONCURRENCY AID-ENTF-PAYMENT-TRANSACTION-FINANCIALTRANSACTIONAMOUNT AID-ENTF-PAYMENT-TRANSACTION-FINANCIALTRANSACTIONFROMACCOUNT AID-ENTF-PAYMENT-TRANSACTION-FINANCIALTRANSACTIONTARGETACCOUNT AID-ENTF-PAYMENT-TRANSACTION-FINANCIALTRANSACTIONDATETIME --workspace "$WS" --person "$R" --reason "already stored by an existing table, or mastered outside the payments hub"
#    The path's two ends AID read from its from/to:
sdem aid confirm PATH-PAY-CORE-HSM --workspace "$WS" --person "$R"

# 2. Approve AID's proposals for the kept tables (object and field mappings) and the links its attributes imply (stored_in, consumes).
sdem approve AID-001-P015 AID-001-P016 AID-001-P017 AID-001-P018 AID-001-P019 AID-001-P020 AID-001-P021 AID-001-P022 AID-001-P023 AID-001-P024 AID-001-P025 AID-001-P026 AID-001-P027 AID-001-P028 AID-001-P029 AID-001-P030 AID-001-P031 AID-001-P040 AID-001-P041 AID-001-P042 AID-001-P087 AID-001-P088 AID-001-P089 AID-001-P090 --proposals "$WS/aid/AID-001-proposals.json" --workspace "$WS" --reviewer "$R" --evidence data_model:PAY-DM-2026 --evidence deployment_design:PAY-DD-01

# 3. State the links nothing proposes (sdem connect) — BIAN objects to the existing tables, field by field; the direct A1→A3 links (D9);
#    events, channels, platform services and where the kept tables are stored.
sdem connect BBO-PAYMENT-TRANSACTION MAPPED_TO ENT-PAY-INSTR --workspace "$WS" --reviewer "$R" --evidence data_model:PAY-DM-2026 --rationale "BIAN's payment transaction is stored in the hub's payment_instruction table (made-up)"
sdem connect BBO-ACCOUNT MAPPED_TO ENT-ACCOUNT-CACHE --workspace "$WS" --reviewer "$R" --evidence data_model:PAY-DM-2026 --rationale "the hub keeps BIAN's account in its account cache (made-up)"
sdem connect BBOA-PAYMENT-TRANSACTION-MONEY-TRANSFER-INSTRUCTION-REFERENCE FIELD_MAPPED_TO F-PAY-INSTR-PAYMENT-INSTRUCTION-REFERENCE --workspace "$WS" --reviewer "$R" --evidence data_model:PAY-DM-2026 --rationale "field mapping in the payments data model (made-up)"
sdem connect BBOA-PAYMENT-TRANSACTION-FINANCIAL-TRANSACTION-FROM-ACCOUNT FIELD_MAPPED_TO F-PAY-INSTR-DEBTOR-ACCOUNT-REFERENCE --workspace "$WS" --reviewer "$R" --evidence data_model:PAY-DM-2026 --rationale "field mapping in the payments data model (made-up)"
sdem connect BBOA-PAYMENT-TRANSACTION-FINANCIAL-TRANSACTION-TARGET-ACCOUNT FIELD_MAPPED_TO F-PAY-INSTR-CREDITOR-ACCOUNT-REFERENCE --workspace "$WS" --reviewer "$R" --evidence data_model:PAY-DM-2026 --rationale "field mapping in the payments data model (made-up)"
sdem connect BBOA-PAYMENT-TRANSACTION-PAYMENT-TRANSACTION-AMOUNT FIELD_MAPPED_TO F-PAY-INSTR-AMOUNT --workspace "$WS" --reviewer "$R" --evidence data_model:PAY-DM-2026 --rationale "field mapping in the payments data model (made-up)"
sdem connect BBOA-PAYMENT-TRANSACTION-FINANCIAL-TRANSACTION-CURRENCY FIELD_MAPPED_TO F-PAY-INSTR-CURRENCY --workspace "$WS" --reviewer "$R" --evidence data_model:PAY-DM-2026 --rationale "field mapping in the payments data model (made-up)"
sdem connect BBOA-PAYMENT-TRANSACTION-MONEY-TRANSFER-VALUE-DATE FIELD_MAPPED_TO F-PAY-INSTR-VALUE-DATE --workspace "$WS" --reviewer "$R" --evidence data_model:PAY-DM-2026 --rationale "field mapping in the payments data model (made-up)"
sdem connect BBOA-PAYMENT-TRANSACTION-PAYMENT-TRANSACTION-STATUS FIELD_MAPPED_TO F-PAY-INSTR-PAYMENT-STATUS --workspace "$WS" --reviewer "$R" --evidence data_model:PAY-DM-2026 --rationale "field mapping in the payments data model (made-up)"
sdem connect BBOA-PAYMENT-TRANSACTION-TRANSACTION-DESCRIPTION FIELD_MAPPED_TO F-PAY-INSTR-REMITTANCE-INFORMATION --workspace "$WS" --reviewer "$R" --evidence data_model:PAY-DM-2026 --rationale "field mapping in the payments data model (made-up)"
sdem connect BBOA-ACCOUNT-ACCOUNT-IDENTIFICATION FIELD_MAPPED_TO F-ACCOUNT-CACHE-ACCOUNT-REFERENCE --workspace "$WS" --reviewer "$R" --evidence data_model:PAY-DM-2026 --rationale "field mapping in the payments data model (made-up)"
sdem connect BBOA-ACCOUNT-ACCOUNT-CURRENCY FIELD_MAPPED_TO F-ACCOUNT-CACHE-CURRENCY --workspace "$WS" --reviewer "$R" --evidence data_model:PAY-DM-2026 --rationale "field mapping in the payments data model (made-up)"
sdem connect BO-ACCOUNT ALIGNED_TO BBO-ACCOUNT --workspace "$WS" --reviewer "$R" --evidence business_glossary:PAY-GLOSSARY --evidence object_alignment_review:PAY-OAR-01 --bian-release 14.0.0 --rationale "the business account is BIAN's account (made-up)"
sdem connect PRC-PAY-01 SERVED_BY SVC-PAY-INIT --workspace "$WS" --reviewer "$R" --evidence process_model:PAY-PM-01 --rationale "capturing and validating uses the payment initiation service (made-up)"
sdem connect ACTOR-CUSTOMER SERVED_BY SVC-PAY-INIT --workspace "$WS" --reviewer "$R" --evidence process_model:PAY-PM-01 --rationale "the customer uses it through the app and API (made-up)"
sdem connect ROLE-PAY-OFFICER SERVED_BY SVC-PAY-INIT --workspace "$WS" --reviewer "$R" --evidence process_model:PAY-PM-01 --rationale "the officer uses it to handle exceptions (made-up)"
sdem connect PRC-PAY-01 AUTOMATED_BY AFN-PAY-VALIDATE --workspace "$WS" --reviewer "$R" --evidence process_model:PAY-PM-01 --rationale "validation is automated (made-up)"
sdem connect BSV-MAKE-PAYMENT REALIZED_BY SVC-PAY-INIT --workspace "$WS" --reviewer "$R" --evidence application_architecture_document:PAY-AAD-01 --rationale "the business service is delivered by the payment initiation service (made-up)"
sdem connect BO-PAYEE MAPPED_TO AID-ENT-PAYEE --workspace "$WS" --reviewer "$R" --evidence data_model:PAY-DM-2026 --rationale "saved payees are kept in the payee table (no BIAN step needed) (made-up)"
sdem connect BEV-PAY-EXECUTED REALIZED_BY EVT-PAY-STATUS --workspace "$WS" --reviewer "$R" --evidence event_design:PAY-ED-01 --rationale "the hub raises PaymentStatusChanged when a payment is executed (made-up)"
sdem connect CHN-OBAPI REALIZED_BY IFC-PAY-API --workspace "$WS" --reviewer "$R" --evidence application_architecture_document:PAY-AAD-01 --rationale "the open banking channel is the Payments API (made-up)"
sdem connect APP-PAY-HUB SERVED_BY TS-MQ --workspace "$WS" --reviewer "$R" --evidence deployment_design:PAY-DD-01 --rationale "the hub publishes events through the messaging service (made-up)"
sdem connect AID-ENT-PAYEE STORED_IN INF-PG-PAY-PROD --workspace "$WS" --reviewer "$R" --evidence deployment_design:PAY-DD-01 --rationale "kept in the payments PostgreSQL (made-up)"
sdem connect AID-ENT-FUNDING-CHECK STORED_IN INF-PG-PAY-PROD --workspace "$WS" --reviewer "$R" --evidence deployment_design:PAY-DD-01 --rationale "kept in the payments PostgreSQL (made-up)"
sdem connect AID-ENT-COMPLIANCE-CHECK STORED_IN INF-PG-PAY-PROD --workspace "$WS" --reviewer "$R" --evidence deployment_design:PAY-DD-01 --rationale "kept in the payments PostgreSQL (made-up)"

sdem check --workspace "$WS"
echo "Done — tell Claude, and it folds v2 into examples/payment-initiation."
